# ── 写入文件 ──
def main():
    existing_meta = {}
    if META_FILE.exists():
        try:
            existing_meta = json.loads(META_FILE.read_text(encoding="utf-8"))
        except Exception:
            pass

    added = 0
    for paper in PAPERS:
        # 生成唯一文件名
        fname = f"{paper['title']}.txt"
        fname = fname.replace("/", "_").replace("\\", "_").replace(":", "：")[:150]

        # 写作文本文件
        content = (
            f"标题：{paper['title']}\n"
            f"作者：{paper['authors']}\n"
            f"期刊：{paper['journal']} ({paper['year']})\n"
            f"关键词：{'；'.join(paper['keywords'])}\n\n"
            f"摘要：{paper['abstract']}\n"
        )
        filepath = DOC_DIR / fname
        if not filepath.exists():
            filepath.write_text(content, encoding="utf-8")

        # 更新元数据
        file_hash = hashlib.md5(filepath.read_bytes()).hexdigest()
        existing_meta[fname] = {
            "title": paper["title"],
            "authors": paper["authors"],
            "journal": paper["journal"],
            "year": paper["year"],
            "category": "论文",
            "tags": paper["keywords"],
            "discipline": "公共管理",
            "main_topic": paper["keywords"][0] if paper["keywords"] else "",
            "size": filepath.stat().st_size,
            "file_hash": file_hash,
        }
        added += 1

    META_FILE.write_text(json.dumps(existing_meta, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"已添加 {added} 篇论文")
    print(f"知识库总计: {len(existing_meta)} 篇文献")
    print(f"下一步: 重启后端后调用 POST /api/v1/chat/build-merged-index 重建索引")


if __name__ == "__main__":
    main()
